mapper.select:
SELECT brp.toolDate, brp.orderDate, brp.billDate, brp.billPayId, brp.billNum, brp.patientId, brp.patientName, brp.mobile, brp.gender, brp.regDentistId, brp.regDentistName, brp.orderAmount, brp.privilegeAmount, brp.actualAmount, brp.receivedAmount, brp.stillOweAmount, brp.remainingOweAmount, brp.payeeUserId, brp.payeeUserName FROM ( SELECT DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) AS toolDate, DATE_FORMAT( bb.order_date, '%Y-%m-%d' ) AS orderDate, DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) AS billDate, bbp.bill_pay_id AS billPayId, bb.bill_num AS billNum, tp.patient_id AS patientId, tp.`name` AS patientName, tp.pinyin_name AS pinyinName, tp.mobile AS mobile, tp.gender AS gender, tp.registered_dentist_id AS regDentistId, tp.regDentistName AS regDentistName, bb.order_amount AS orderAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bbp.org_id as orgId, bbp.received_amount AS receivedAmount, bbp.still_owe_amount AS stillOweAmount, bb.debt_amount AS remainingOweAmount, bbp.payee_user_id AS payeeUserId, be.employee_name AS payeeUserName FROM base_bill_pay bbp LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id LEFT JOIN base_employee be ON bbp.payee_user_id = be.user_id LEFT JOIN ( SELECT btp.treatment_id, bp.patient_id, bp.`name`, bp.pinyin_name, bp.mobile, bp.gender, btp.registered_dentist_id, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) tp ON bbp.treatment_id = tp.treatment_id ) brp
and brp.orgId = #{query.orgId}
and brp.billNum like concat('%', #{query.billNum}, '%')
and concat(IFNULL(brp.patientName, ''),IFNULL(brp.pinyinName, ''), IFNULL(brp.mobile, '')) like concat('%', #{query.keyWord}, '%')
and brp.toolDate >= #{query.tollStartDate}
and brp.toolDate <= #{query.tollEndDate}
and brp.billDate >= #{query.billStartDate}
and brp.billDate <= #{query.billEndDate}
and brp.regDentistId in
#{item}
ORDER BY brp.toolDate DESC

SELECT
IFNULL(SUM( bbp.totalReceivedDebtAmount ), 0) AS totalReceivedDebtAmount,
IFNULL(SUM( bbp.totalReceivedAmount ), 0) AS totalReceivedAmount,
IFNULL(SUM( bbp.totalBillRefundAmount ), 0) AS totalBillRefundAmount,
IFNULL(SUM( bbp.totalClinicCollectionAmount ), 0) AS totalClinicCollectionAmount,
IFNULL(SUM( bbp.totalClinicCollectedAmount ), 0) AS totalClinicCollectedAmount
FROM
(
SELECT
bo.org_id,
IFNULL( bbp.totalReceivedDebtAmount, 0 ) AS totalReceivedDebtAmount,
IFNULL( bbp1.totalReceivedAmount, 0 ) AS totalReceivedAmount,
IFNULL( br.totalBillRefundAmount, 0 ) AS totalBillRefundAmount,
IFNULL( bbp2.totalClinicCollectionAmount, 0 ) AS totalClinicCollectionAmount,
IFNULL( bbp3.totalClinicCollectedAmount, 0 ) AS totalClinicCollectedAmount
FROM
base_organization bo
LEFT JOIN (
SELECT
bbp.org_id,
SUM( bbp.received_amount ) AS totalReceivedDebtAmount
FROM
(
SELECT
bbp.org_id,
bbp.received_amount,
bbp.payee_date,
bb.bill_date
FROM
base_bill_pay bbp
LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id



            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y') <= #{query.endDate}



) bbp
WHERE
bbp.payee_date != bbp.bill_date
GROUP BY
bbp.org_id
) bbp ON bo.org_id = bbp.org_id
LEFT JOIN (
SELECT
bbp.org_id,
SUM( bbp.received_amount ) AS totalReceivedAmount
FROM
base_bill_pay bbp



            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y') <= #{query.endDate}



GROUP BY
bbp.org_id
) bbp1 ON bo.org_id = bbp1.org_id
LEFT JOIN (
SELECT
br.org_id,
SUM( br.refund_amount ) AS totalBillRefundAmount
FROM
base_refund br



            and DATE_FORMAT( br.refund_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( br.refund_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( br.refund_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( br.refund_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( br.refund_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( br.refund_date, '%Y') <= #{query.endDate}



GROUP BY
br.org_id
) br ON bo.org_id = br.org_id
LEFT JOIN (
SELECT
bbp.tollOrgId,
SUM( bbp.received_amount ) AS totalClinicCollectionAmount
FROM
(
SELECT
bbp.org_id AS tollOrgId,
bbp.received_amount,
bb.org_id AS billOrgId
FROM
base_bill_pay bbp
LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id



            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y') <= #{query.endDate}



) bbp
WHERE
bbp.tollOrgId != bbp.billOrgId
GROUP BY
bbp.tollOrgId
) bbp2 ON bo.org_id = bbp2.tollOrgId
LEFT JOIN (
SELECT
bbp.billOrgId,
SUM( bbp.received_amount ) AS totalClinicCollectedAmount
FROM
(
SELECT
bbp.org_id AS tollOrgId,
bbp.received_amount,
bb.org_id AS billOrgId
FROM
base_bill_pay bbp
LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id



            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y') <= #{query.endDate}



) bbp
WHERE
bbp.tollOrgId != bbp.billOrgId
GROUP BY
bbp.billOrgId
) bbp3 ON bo.org_id = bbp3.billOrgId
) bbp


        and bbp.org_id in

            #{item}
